import{_ as t,c as o,o as n,ae as a}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Icon Element","description":"Icon Element","frontmatter":{"title":"Icon Element","description":"Icon Element"},"headers":[],"relativePath":"guide/drag-drop-elements/icon-element.md","filePath":"guide/drag-drop-elements/icon-element.md"}'),i={name:"guide/drag-drop-elements/icon-element.md"};function l(s,e,c,r,d,m){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="icon-element" tabindex="-1">Icon Element <a class="header-anchor" href="#icon-element" aria-label="Permalink to &quot;Icon Element&quot;">​</a></h1><p>One of the most useful elements of a table is the “Icon.” Introducing the Icon element, the powerful feature of Ninja Tables. It allows you to add icons to your WordPress tables. This can be a great way to add visual interest to data tables and make them easier to scan. Ninja Tables offers an “Icon” element to give your tables an eye-catching view. Add an Icon element to Ninja Tables and customize the color, size, or anything. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Icon-element-in-table-1024x546.png" alt="Icon element in table"> Once you pick the icon element and drop it on a cell, Ninja Tables shows you a default icon of the logo. Of course, it&#39;s customizable.</p><h2 id="icon-element-specific-properties" tabindex="-1"><strong>Icon Element Specific Properties</strong> <a class="header-anchor" href="#icon-element-specific-properties" aria-label="Permalink to &quot;**Icon Element Specific Properties**&quot;">​</a></h2><ul><li><strong>Color:</strong> You can change the color of the Icon. By default, it is set to Black.</li><li><strong>Icon Size:</strong> You can change the size of the Icon. By default, it is set to 15.</li><li><strong>Alignment:</strong> You can align the icon to the left, right, or center. By default, it is set to Center.</li><li><strong>Choose Icon:</strong> You can upload your own image as an icon to add to the table.</li><li><strong>Icon Library:</strong> A library of Icons to choose from.</li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>We hope this documentation helps you understand the functionality of this Drag &amp; Drop icon element. Let us know your thoughts and questions in the comment box.</p>',6)])])}const p=t(i,[["render",l]]);export{h as __pageData,p as default};
